import { writeFileSync } from 'node:fs';
import { COSMETIC_CHEST_PRICE, ITEMS, LOOT_POOL } from '../shared/cosmetics.mjs';
import { rarityFor } from '../shared/rarities.mjs';
import { RARITY_STOCK, LOOT_WEIGHT } from '../shared/economy-policy.mjs';
import { RIGS, STOCK_RIGS } from '../shared/rigs.mjs';

const commercial = Object.values(ITEMS).filter(item => !item.expeditionOnly);

const lines = [
  '// Generated by scripts/near-catalog.mjs.',
  'pub const CHEST_PRICE: u64 = ' + COSMETIC_CHEST_PRICE + ';',
  'pub const LOOT_COUNT: usize = ' + LOOT_POOL.length + ';',
  'pub const ITEMS: &[(&str, &str, u64, u64)] = &[',
  ...commercial.map(item =>
    '    ("' + item.id + '", "' + item.slot + '", ' + (item.price ?? 0) + ', ' + (item.scrapCost ?? 0) + '),'),
  '];',
  'pub const ITEM_RARITY: &[&str] = &[' + commercial.map(item => '"' + rarityFor(item) + '"').join(', ') + '];',
  'pub const ITEM_CAP: &[u8] = &[' + commercial.map(item => item.price || item.scrapCost ? RARITY_STOCK[rarityFor(item)] : 0).join(', ') + '];',
  'pub const ITEM_LOOT_WEIGHT: &[u32] = &[' + commercial.map(item => LOOT_POOL.includes(item.id) ? LOOT_WEIGHT[rarityFor(item)] : 0).join(', ') + '];',
  'pub const RIG_RARITY: &[&str] = &[' + STOCK_RIGS.map(id => '"' + rarityFor({ ...RIGS[id], id }) + '"').join(', ') + '];',
  'pub const RIG_CAP: &[u8] = &[' + STOCK_RIGS.map(id => RARITY_STOCK[rarityFor({ ...RIGS[id], id })]).join(', ') + '];',
  'pub const VOYAGE_ITEMS: &[&str] = &[',
  ...Object.values(ITEMS).filter(item => item.expeditionOnly).map(item => '    "' + item.id + '",'),
  '];',
  '',
];
if (LOOT_POOL.some((id, index) => Object.keys(ITEMS)[index] !== id)) {
  throw new Error('Loot entries must precede the décor entries.');
}
writeFileSync(new URL('../near-arena/src/catalog_data.rs', import.meta.url), lines.join('\n'));
